package main

import (
	"context"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

func resourceGraphQLQuery() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceGraphQLQueryCreate,
		ReadContext:   resourceGraphQLQueryRead,
		DeleteContext: resourceGraphQLQueryDelete,
		Schema: map[string]*schema.Schema{
			"endpoint": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"query_template": {
				Type:     schema.TypeString,
				Required: true,
				ForceNew: true,
			},
			"variables": {
				Type:     schema.TypeMap,
				Optional: true,
				ForceNew: true,
				Elem:     &schema.Schema{Type: schema.TypeString},
			},
			"result": {
				Type:     schema.TypeString,
				Computed: true,
			},
			"auth_token_file": {
				Type:     schema.TypeString,
				Optional: true,
				Default:  "/etc/terraform-provider/auth_token",
				ForceNew: true,
			},
		},
	}
}

func buildQuery(template string, variables map[string]interface{}) string {
	// VULNERABILITY: Direct string interpolation into GraphQL query
	// No sanitization of variable values allows GraphQL injection
	result := template
	for key, val := range variables {
		placeholder := fmt.Sprintf("${%s}", key)
		result = strings.ReplaceAll(result, placeholder, fmt.Sprintf("%v", val))
	}
	return result
}

func resourceGraphQLQueryCreate(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	endpoint := d.Get("endpoint").(string)
	queryTemplate := d.Get("query_template").(string)
	variables := d.Get("variables").(map[string]interface{})
	authTokenFile := d.Get("auth_token_file").(string)

	// Read auth token from filesystem
	authToken := ""
	if tokenBytes, err := ioutil.ReadFile(authTokenFile); err == nil {
		authToken = strings.TrimSpace(string(tokenBytes))
	}

	// Build query with unsanitized variable interpolation
	query := buildQuery(queryTemplate, variables)

	// Wrap in standard GraphQL JSON payload
	payload := fmt.Sprintf(`{"query": %q}`, query)

	req, err := http.NewRequestWithContext(ctx, "POST", endpoint, strings.NewReader(payload))
	if err != nil {
		return diag.FromErr(err)
	}
	req.Header.Set("Content-Type", "application/json")
	if authToken != "" {
		req.Header.Set("Authorization", "Bearer "+authToken)
	}

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return diag.FromErr(err)
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return diag.FromErr(err)
	}

	d.SetId(fmt.Sprintf("%s-%d", endpoint, os.Getpid()))
	d.Set("result", string(body))

	return nil
}

func resourceGraphQLQueryRead(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	return nil
}

func resourceGraphQLQueryDelete(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	d.SetId("")
	return nil
}

